function deleteOriginalCustomColor(s,id,color){const base=originalBaseColorCount(s,id),ci=color-base,list=s.originalCustomColorways?.[id]||[];if(ci<0||ci>=list.length)return false;list.splice(ci,1);if(s.inventory?.[id]){const i=s.inventory[id];i.colorStock=shiftColorObject(i.colorStock,color);i.colorSold=shiftColorObject(i.colorSold,color);if(Number(i.shootColor)>color)i.shootColor--}if(s.producedColorHistory?.[id])s.producedColorHistory[id]=shiftColorObject(s.producedColorHistory[id],color);for(const x of s.production||[])if(x.id===id&&Number(x.color)>color)x.color--;for(const x of s.orderLedger||[])if(x.productId===id&&x.channel==="original"&&Number(x.color)>color)x.color--;for(const x of s.history?.logistics||[])if(x.id===id&&Number(x.color)>color)x.color--;for(const x of s.history?.sales||[])if(x.id===id&&x.colorSales)x.colorSales=shiftColorObject(x.colorSales,color);for(const x of s.pendingReturns||[])if(x.id===id&&Number(x.color)>color)x.color--;for(const x of s.sponsorships||[])if(x.productId===id&&Number(x.color)>color)x.color--;if(s.colorDemandProfiles)delete s.colorDemandProfiles[id];return true}
function itemSummary(s,items){return(items||[]).map(x=>{const p=pdef(x.id,s);return p?`${p.name} · ${colorLabel(s,p.id,x.color)} ×${x.qty}`:""}).filter(Boolean).join(" / ")}
function invEnsure(s,id){if(!s.inventory[id]){const p=pdef(id,s);s.inventory[id]={stock:0,price:p.retail,shoot:0,sold:0,avgCost:0,source:p.source,colorStock:{},colorSold:{},saleActive:true,model:"female",shootColor:0,firstStockDay:0,firstStockSeq:0,lastStockDay:0,lastStockSeq:0,lastSoldDay:0,lastDaySoldQty:0}}if(!s.inventory[id].colorStock)s.inventory[id].colorStock={0:s.inventory[id].stock||0};if(!s.inventory[id].colorSold)s.inventory[id].colorSold={};if(s.inventory[id].saleActive==null)s.inventory[id].saleActive=true;if(s.inventory[id].firstStockDay==null)s.inventory[id].firstStockDay=0;if(s.inventory[id].firstStockSeq==null)s.inventory[id].firstStockSeq=(s.inventory[id].firstStockDay||0)*1000000;if(s.inventory[id].lastStockDay==null)s.inventory[id].lastStockDay=0;if(s.inventory[id].lastStockSeq==null)s.inventory[id].lastStockSeq=(s.inventory[id].lastStockDay||0)*1000000;if(s.inventory[id].lastSoldDay==null)s.inventory[id].lastSoldDay=0;if(s.inventory[id].lastDaySoldQty==null)s.inventory[id].lastDaySoldQty=0;return s.inventory[id]}
function markStockArrival(s,i,day=s.day){const d=Number(day)||s.day;s.stockOrderByDay??={};const n=(Number(s.stockOrderByDay[d])||0)+1;s.stockOrderByDay[d]=n;if(!(Number(i.firstStockDay)>0)){i.firstStockDay=d;i.firstStockSeq=d*1000000+n}i.lastStockDay=d;i.lastStockSeq=d*1000000+n}
function ensureFirstStockDays(s){for(const [id,i] of Object.entries(s.inventory||{})){if(Number(i.firstStockDay)>0)continue;const days=[];for(const x of s.history?.logistics||[]){const k=String(x.kind||"");if(x.id===id&&Number(x.day)>0&&k.includes("입고")&&!k.includes("예정")&&!k.includes("주문"))days.push(Number(x.day))}for(const x of s.orderLedger||[])if(x.productId===id&&Number(x.completedDay)>0)days.push(Number(x.completedDay));if(!days.length&&Number(s.sampledDay?.[id])>0)days.push(Number(s.sampledDay[id]));if(!days.length&&Number(i.lastStockDay)>0)days.push(Number(i.lastStockDay));if(days.length){const d=Math.min(...days);i.firstStockDay=d;i.firstStockSeq=d*1000000}}return s}
function markColorHistory(s,id,color,kind){const key=kind==="original"?"producedColorHistory":"purchasedColorHistory";s[key]??={};s[key][id]??={};s[key][id][String(Number(color)||0)]=true}
function ensureMerchHistory(s){s.purchasedColorHistory??={};s.producedColorHistory??={};for(const [id,i] of Object.entries(s.inventory||{})){if(i.saleActive==null)i.saleActive=true;const p=pdef(id,s);if(!p)continue;const key=p.source==="ORIGINAL"?"original":"edit";for(const [c,q] of Object.entries(i.colorStock||{}))if(Number(q)>0)markColorHistory(s,id,c,key)}for(const x of s.orderLedger||[]){if(!x?.productId)continue;if(x.channel==="original")markColorHistory(s,x.productId,x.color,"original");else if(x.channel==="market"||x.channel==="reorder")markColorHistory(s,x.productId,x.color,"edit")}for(const x of s.history?.logistics||[]){if(!x?.id)continue;const kind=String(x.kind||"");if(kind.includes("온라인 반품"))continue;const p=pdef(x.id,s);if(!p)continue;if(p.source==="ORIGINAL"||kind.includes("자체제작")||kind.includes("불량 재작업"))markColorHistory(s,x.id,x.color,"original");else if(kind.includes("입고")||kind.includes("주문")||kind.includes("미송"))markColorHistory(s,x.id,x.color,"edit")}s.version=Math.max(Number(s.version)||0,16);return s}
function ensureColorSalesBalance(s){if(!s.colorSalesMigrated){for(const i of Object.values(s.inventory||{}))i.colorSold={};for(const x of s.history?.sales||[]){const i=s.inventory?.[x.id];if(!i||!x.colorSales)continue;i.colorSold??={};for(const [k,q] of Object.entries(x.colorSales))i.colorSold[k]=(i.colorSold[k]||0)+(Number(q)||0)}s.colorSalesMigrated=true}for(const i of Object.values(s.inventory||{}))i.colorSold??={};return s}
function avgCost(a,b,c,d){return a+c?Math.round((a*b+c*d)/(a+c)):0}
function colorOk(id,c,s){const a=stateColorways(s,id);return Number.isInteger(Number(c))&&Number(c)>=0&&Number(c)<a.length}
function addColor(i,c,q){const k=String(c);i.colorStock[k]=(i.colorStock[k]||0)+q}
function takeColors(i,n){const out=[];for(let j=0;j<n;j++){const k=Object.keys(i.colorStock||{}).find(x=>i.colorStock[x]>0);if(k==null)break;i.colorStock[k]--;out.push(Number(k))}return out}

