function reviewRatingFor(p,price,seed){const ratio=(Number(price)||p.retail)/Math.max(1,p.retail);let base=1.68+clamp(Number(p.quality)||3,1,5)*.63;if(ratio>=1.35)base-=.9;else if(ratio>=1.2)base-=.55;else if(ratio>=1.08)base-=.2;else if(ratio<=.7)base+=.18;else if(ratio<=.86)base+=.08;base+=(r(seed)-.5)*1.25;return Math.round(clamp(base,1,5))}
