function productSalesProfile(s,id){
  if(!s.productSalesProfiles||typeof s.productSalesProfiles!=='object'||Array.isArray(s.productSalesProfiles))s.productSalesProfiles={};
  const defaults=defaultProductSalesProfile(id),raw=s.productSalesProfiles[id];
  const profile=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
  const ranges={popularity:[0,100],demand:[.5,1.5],sellSpeed:[.5,1.5],trendAffinity:[.5,1.5],priceSensitivity:[.5,2]};
  for(const [key,[min,max]] of Object.entries(ranges))if(typeof profile[key]!=='number'||!Number.isFinite(profile[key])||profile[key]<min||profile[key]>max)profile[key]=defaults[key];
  profile.version=1;s.productSalesProfiles[id]=profile;return profile;
}
function ensureProductSalesProfiles(s){
  for(const p of [...PRODUCTS,...(s.generatedProducts||[]),...ORIGINALS,...(s.generatedOriginals||[])])productSalesProfile(s,p.id);
  return s;
}
// Composition seam for future trend/event work. Existing providers remain authoritative.
function productSalesFactors(s,p,i,currentTrend){
  const profile=productSalesProfile(s,p.id),b=PRODUCT_SALES_BALANCE;
  const base=clamp((.7+profile.popularity*.006)*profile.demand*profile.sellSpeed,b.baseMin,b.baseMax);
  const price=clamp(Math.pow(p.retail/Math.max(1,i.price),profile.priceSensitivity),b.priceMin,b.priceMax);
  return {base,price,photo:i.shoot>0?1+(clamp(i.shoot,1,3)-1)*b.photoStep:0,
    trend:p.trend===currentTrend?1+b.trendBoost*profile.trendAffinity:1,event:eventSalesFactor(s,p)};
}

