    if(!p||!state.sampled[p.id])return{ok:false,error:"샘플 구매 이력이 있는 상품만 앱 리오더할 수 있습니다."};
    if(!colorOk(p.id,x.color,state))return{ok:false,error:"컬러를 선택해주세요."};
    if(!Number.isInteger(q)||q<1||q>200)return{ok:false,error:"컬러별 수량은 1~200장으로 설정해주세요."};
